package com.example.madfinalproject;
import android.content.Intent; import android.os.Bundle; import android.widget.TextView; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity;
public class PtePreparationActivity extends AppCompatActivity {protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_ielts_preparation);PteUiAdapter.apply(findViewById(android.R.id.content));((TextView)findViewById(R.id.tabOverview)).setTextColor(PteUiAdapter.TEAL);findViewById(R.id.btnBack).setOnClickListener(v->finish());findViewById(R.id.btnContinue).setOnClickListener(v->Toast.makeText(this,"Continuing PTE Listening",Toast.LENGTH_SHORT).show());findViewById(R.id.btnEditScore).setOnClickListener(v->Toast.makeText(this,"Edit target PTE score",Toast.LENGTH_SHORT).show());findViewById(R.id.tabLessons).setOnClickListener(v->open(PteLessonsActivity.class));findViewById(R.id.tabPractice).setOnClickListener(v->open(PtePracticeActivity.class));findViewById(R.id.tabMockTests).setOnClickListener(v->open(PteMockTestsActivity.class));findViewById(R.id.tabReports).setOnClickListener(v->open(PteReportsActivity.class));}private void open(Class<?> c){startActivity(new Intent(this,c));}}
